                /** @description Only designs received (`committedAt`) at or before this time, in epoch milliseconds. */
                receivedTo?: number | null;
                /** @description By when the designs were received: `desc`, newest first, unless `asc` asks for the oldest first. */
                order?: "asc" | "desc";
                template?: string;
                externalRef?: string;
                /** @description `true` lists only standing designs, `false` only the rest; left out, both. */
