                            changeRequested: boolean;
                            committedAt: number;
                            /** @description Whether `DELETE /v1/designs/{id}` would take the design now: it is not approved, and no print of it exists, of any revision and in any status. */
                            deletable: boolean;
                            duplicatedFrom: string | null;
                            /** @description Your own reference for the design, as sent on the commit or `PUT /v1/designs/{id}/external-ref`, or null. */
                            externalRef: string | null;
                            /** @description Whether any print of the design has been ordered: `hasOrder` of `GET /v1/designs/{id}`. */
                            hasOrder: boolean;
                            /** @description Whether the design has a print file: a completed print of any of its revisions. Unlike `hasPrint` of `GET /v1/designs/{id}`, a print of an earlier revision counts. */
                            hasPrintFile: boolean;
                            id: string;
                            /** @description Where the design came from: the door it was committed through. A duplicate's is whoever duplicated it. */
                            origin: {
                                /** @description The designer link's id, the key's id, or the connected store's site address. Null for `studio`, and for a key set in the deployment's configuration rather than made in the workspace. */
                                id: string | null;
                                /** @description `link`: a designer link's page made it. `studio`: a member made it, in the studio or through an MCP key. `secret_key` and `publishable_key`: committed with one of your keys. `store`: committed by a connected store, with any key its site was given. */
                                kind: string;
                            };
                            /** @description The size the design prints at, without bleed: the `widthMm` and `heightMm` its proof or commit named, or the size fitted for one that named none. A store checks it, with `templateVersion`, `blankId` and `placementId`, against what the product variation sells before accepting the add to cart, since the proof is made in the customer's browser. Null only for a stored document that holds no usable print size. */
                            printSize: {
                                /** @description The print's trim height, in millimetres. */
                                heightMm: number;
                                /** @description The print's trim width, in millimetres. */
                                widthMm: number;
                            } | null;
                            proofId: string | null;
                            proofRevision: number | null;
                            revision: number;
                            /** @description Whether this is a standing design: the workspace's own design for a fixed product, made by `POST /v1/designs/standing` from a template version as its author left it. A standing design is ordered any number of times, each order reusing the print of its current revision. False for a customer's design. */
                            standing: boolean;
                            status: string;
                            templateBaseId: string;
                            /** @description Whether the design's template was deleted. The design keeps its template's name and version; the template itself can no longer be opened. */
                            templateDeleted: boolean;
                            templateId: string;
                            templateName: string | null;
                            /** @description The version of the template the design was made from: `templateId` after its `@`. A design committed from a proof token was made from the proof's version, whatever the template's latest is now. */
                            templateVersion: number | null;
